// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount to allow the fuzzer to find an amount that causes depositsCount to wrap
    function testFuzz_property(uint256 value, address payer) public {
        // keep payer non-zero and give it funds; allow full uint range to let overflow occur in mutant
        vm.assume(payer != address(0));
        // fund the payer so it can send value
        vm.deal(payer, value);

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // make the call from payer sending `value` wei to trigger receive()
        vm.prank(payer);
        (bool ok, ) = address(c).call{value: value}("");
        // the reference contract's receive() always succeeds for any value (no revert), so ok should be true
        // but we don't assert on ok directly; we only assert the invariant below which reads c

        uint256 after = c.depositsCount();

        // General invariant: receive() increases depositsCount by exactly 1 (i.e., after == before + 1)
        // This holds for the reference contract for all inputs; the mutant that removed the safety check
        // can overflow/wrap depositsCount for some input values, breaking this invariant.
        assertTrue(after == before + 1);
    }
}

