pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 senderStartBalance, uint256 sendValue) public {
        // keep wide bounds but ensure the sender has at least sendValue
        sendValue = bound(sendValue, 0, type(uint256).max);
        senderStartBalance = bound(senderStartBalance, sendValue, type(uint256).max);

        // choose a sender address and fund it
        address sender = address(uint160(uint256(keccak256(abi.encodePacked(sendValue, senderStartBalance, block.timestamp)))));
        vm.deal(sender, senderStartBalance);

        // record prior depositsCount
        uint256 before = c.depositsCount();

        // perform the payable call to receive via prank
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: sendValue}("");
        // ensure the call completed (ok may be true even if no state change)
        // read after state
        uint256 after_ = c.depositsCount();

        // General rule: depositsCount must not decrease after receive call
        assertTrue(after_ >= before);
    }
}

