pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: starting deposits count value we will force into storage by making repeated deposits
    function testFuzz_property(uint256 times, uint256 sendAmount) public {
        // keep domains wide but sensible
        times = bound(times, 0, 300); // we only need to simulate many deposits but avoid extremely long loops
        sendAmount = bound(sendAmount, 0, 1 ether);

        // We'll perform `times` successful deposits to increase depositsCount from 0 upward.
        // Use an actor to send ETH to the contract so receive() executes.
        address depositor = address(0xBEEF);
        vm.deal(depositor, 10 ether);

        for (uint256 i = 0; i < times; i++) {
            vm.prank(depositor);
            // send a small amount (possibly zero) which still triggers receive
            (bool ok, ) = address(c).call{value: sendAmount}("");
            require(ok);
        }

        uint256 before = c.depositsCount();

        // Now craft an input that will reveal the mutant: call receive() once more from depositor.
        vm.prank(depositor);
        (bool okAfter, ) = address(c).call{value: sendAmount}("");

        // The general rule: for the correct contract, any successful receive() call cannot make depositsCount wrap
        // and thus cannot make depositsCount_after < depositsCount_before. We assert that property over c's getter.
        uint256 after = c.depositsCount();

        // exactly one assertion: correct contract guarantees after >= before for all inputs; mutant can violate it
        assertTrue(after >= before);
    }
}

