contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and the value sent; the property: after a successful call to receive, depositsCount == old+1
    function testFuzz_property(address sender, uint128 value) public {
        // keep sender non-zero (EOA) to be widely admissible; allow zero though as well
        // bound value to something reasonable so vm.deal works and to include zero
        uint256 amt = bound(uint256(value), 0, 1 ether);

        // record previous count
        uint256 prev = c.depositsCount();

        // fund sender so they can send
        vm.deal(sender, amt);

        bool ok;
        // perform the external payable call to receive via low-level send from sender
        vm.prank(sender);
        try c.call{value: amt}("") {
            // call succeeded
            ok = true;
        } catch {
            // call reverted
            ok = false;
        }

        // The universal property we assert: if the call succeeded, depositsCount == prev + 1
        // This holds for the reference implementation for all inputs; the mutant will sometimes revert (ok==false)
        if (ok) {
            assertTrue(c.depositsCount() == prev + 1);
        } else {
            // If the call reverted, still assert that depositsCount did not increase (defensive check)
            // (This branch is allowed but not required by the primary universal property above.)
            assertTrue(c.depositsCount() == prev);
        }
    }
}

