pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender and amount. We require amount > 0 because the bug only affects payable receives
    // and a zero-value receive may be treated differently; keep domain wide otherwise.
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender usable
        vm.assume(sender != address(0));
        // bound amount to a reasonable range but allow zero excluded by assumption below
        amount = bound(amount, 0, 1 ether);
        vm.assume(amount > 0);

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        // record depositsCount before
        uint before = c.depositsCount();

        // make the payable call as sender to trigger receive()
        bool ok;
        vm.prank(sender);
        // call via low-level to trigger receive fallback; using call on address(c)
        (ok, ) = address(c).call{value: amount}("");

        // If the reference contract, for any nonzero amount and any caller, always accepts and increments,
        // then either the call succeeded (ok == true) and depositsCount == before+1.
        // The single assertion below checks the universal property that the call succeeds and depositsCount advanced by 1.
        // This holds for the reference C for all admissible inputs, but the mutant with strict '>' can revert
        // when depositsCount == 0 and thus fail this assertion for some fuzzed inputs.
        assertTrue(ok && c.depositsCount() == before + 1);
    }
}
